window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a66c9f52533e2d27"]={"versions": [{"id": "FIG-a66c9f52533e2d27", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung speicherbezogener Diagnosedienste im Rahmen des AUTOSAR Diagnostic Extract Templates (DEXT). Es spezifiziert die Struktur zur Adressierung von Speicherbereichen und Übertragungsdiensten (insbesondere UDS-Dienste 0x23 ReadMemoryByAddress, 0x3D WriteMemoryByAddress, 0x34 RequestDownload, 0x35 RequestUpload sowie 0x36 TransferData / 0x37 RequestTransferExit).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>DiagnosticServiceInstance</code> (abstrakt, spezialisiert <code>DiagnosticCommonElement</code>): Basisklasse aller Diagnosedienst-Instanzen.</li>\n<li><code>DiagnosticMemoryByAddress</code> (abstrakt): Erbt von <code>DiagnosticServiceInstance</code>.</li>\n<li><code>DiagnosticTransferExit</code> und <code>DiagnosticDataTransfer</code>: Konkrete Spezialisierungen von <code>DiagnosticMemoryByAddress</code> zur Modellierung der Datenübertragungsphasen.</li>\n<li><code>DiagnosticMemoryAddressableRangeAccess</code> (abstrakt): Spezialisierung von <code>DiagnosticMemoryByAddress</code>. Besitzt eine Assoziation <code>+memoryRange</code> mit Multiplizität <code>0..*</code> zu <code>DiagnosticMemoryIdentifier</code>.</li>\n<li><code>DiagnosticMemoryIdentifier</code> (spezialisiert <code>DiagnosticCommonElement</code>): Definiert die Adressbereiche über die Attribute:</li>\n<li><code>+ id :PositiveInteger [0..1]</code></li>\n<li><code>+ memoryHighAddress :PositiveInteger [0..1]</code></li>\n<li><code>+ memoryHighAddressLabel :String [0..1]</code></li>\n<li><code>+ memoryLowAddress :PositiveInteger [0..1]</code></li>\n<li><code>+ memoryLowAddressLabel :String [0..1]</code></li>\n<li>Konkrete Dienstklassen erben von <code>DiagnosticMemoryAddressableRangeAccess</code>:</li>\n<li><code>DiagnosticWriteMemoryByAddress</code> (0x3D)</li>\n<li><code>DiagnosticReadMemoryByAddress</code> (0x23)</li>\n<li><code>DiagnosticRequestDownload</code> (0x34)</li>\n<li><code>DiagnosticRequestUpload</code> (0x35)</li>\n<li>Zugriffsschutz: <code>DiagnosticAccessPermission</code> (spezialisiert <code>DiagnosticCommonElement</code>) ist über die gerichtete Assoziation <code>+accessPermission</code> mit Multiplizität <code>0..1</code> sowohl an <code>DiagnosticServiceInstance</code> als auch an <code>DiagnosticMemoryIdentifier</code> angebunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die Konfigurationsstruktur zur Laufzeitinitialisierung des AUTOSAR Diagnostic Communication Managers (DCM), welcher anhand der definierten Adressbereiche (<code>memoryLowAddress</code> bis <code>memoryHighAddress</code>) und Berechtigungen (<code>accessPermission</code>) eingehende UDS-Dienstanfragen validiert und an den Speichertreiber oder Download-/Upload-Handler weiterleitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Erstellung und Validierung von AUTOSAR DEXT-Dateien (<code>ARXML</code>). Die Kardinalität <code>0..*</code> bei <code>+memoryRange</code> erlaubt es einem Dienst, mehrere Adressbereiche zu referenzieren. Über die optionale Verknüpfung <code>+accessPermission [0..1]</code> können Sicherheits- und Sitzungsbedingungen für den Gesamtdienst sowie spezifisch je Speicherbereich (<code>DiagnosticMemoryIdentifier</code>) deklariert werden. Labels dienen der symbolischen Zuordnung im Entwicklungswerkzeug.</p>"}, {"id": "FIG-9fdb73b17e3ed139", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung speicherbezogener Diagnosedienste im Rahmen des AUTOSAR Diagnostic Extract Templates (DEXT). Es spezifiziert die Struktur zur Adressierung von Speicherbereichen und Übertragungsdiensten (insbesondere UDS-Dienste 0x23 ReadMemoryByAddress, 0x3D WriteMemoryByAddress, 0x34 RequestDownload, 0x35 RequestUpload sowie 0x36 TransferData / 0x37 RequestTransferExit).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>DiagnosticServiceInstance</code> (abstrakt, spezialisiert <code>DiagnosticCommonElement</code>): Basisklasse aller Diagnosedienst-Instanzen.</li>\n<li><code>DiagnosticMemoryByAddress</code> (abstrakt): Erbt von <code>DiagnosticServiceInstance</code>.</li>\n<li><code>DiagnosticTransferExit</code> und <code>DiagnosticDataTransfer</code>: Konkrete Spezialisierungen von <code>DiagnosticMemoryByAddress</code> zur Modellierung der Datenübertragungsphasen.</li>\n<li><code>DiagnosticMemoryAddressableRangeAccess</code> (abstrakt): Spezialisierung von <code>DiagnosticMemoryByAddress</code>. Besitzt eine Assoziation <code>+memoryRange</code> mit Multiplizität <code>0..*</code> zu <code>DiagnosticMemoryIdentifier</code>.</li>\n<li><code>DiagnosticMemoryIdentifier</code> (spezialisiert <code>DiagnosticCommonElement</code>): Definiert die Adressbereiche über die Attribute:</li>\n<li><code>+ id: PositiveInteger [0..1]</code></li>\n<li><code>+ memoryHighAddress: PositiveInteger [0..1]</code></li>\n<li><code>+ memoryHighAddressLabel: String [0..1]</code></li>\n<li><code>+ memoryLowAddress: PositiveInteger [0..1]</code></li>\n<li><code>+ memoryLowAddressLabel: String [0..1]</code></li>\n<li>Konkrete Dienstklassen erben von <code>DiagnosticMemoryAddressableRangeAccess</code>:</li>\n<li><code>DiagnosticWriteMemoryByAddress</code> (0x3D)</li>\n<li><code>DiagnosticReadMemoryByAddress</code> (0x23)</li>\n<li><code>DiagnosticRequestDownload</code> (0x34)</li>\n<li><code>DiagnosticRequestUpload</code> (0x35)</li>\n<li>Zugriffsschutz: <code>DiagnosticAccessPermission</code> (spezialisiert <code>DiagnosticCommonElement</code>) ist über die gerichtete Assoziation <code>+accessPermission</code> mit Multiplizität <code>0..1</code> sowohl an <code>DiagnosticServiceInstance</code> als auch an <code>DiagnosticMemoryIdentifier</code> angebunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die Konfigurationsstruktur zur Laufzeitinitialisierung des AUTOSAR Diagnostic Communication Managers (DCM), welcher anhand der definierten Adressbereiche (<code>memoryLowAddress</code> bis <code>memoryHighAddress</code>) und Berechtigungen (<code>accessPermission</code>) eingehende UDS-Dienstanfragen validiert und an den Speichertreiber oder Download-/Upload-Handler weiterleitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Erstellung und Validierung von AUTOSAR DEXT-Dateien (<code>ARXML</code>). Die Kardinalität <code>0..*</code> bei <code>+memoryRange</code> erlaubt es einem Dienst, mehrere Adressbereiche zu referenzieren. Über die optionale Verknüpfung <code>+accessPermission [0..1]</code> können Sicherheits- und Sitzungsbedingungen für den Gesamtdienst sowie spezifisch je Speicherbereich (<code>DiagnosticMemoryIdentifier</code>) deklariert werden. Labels dienen der symbolischen Zuordnung im Entwicklungswerkzeug.</p>"}], "trans": [{"from": "FIG-a66c9f52533e2d27", "to": "FIG-9fdb73b17e3ed139", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>DiagnosticMemoryIdentifier</code>: Vereinheitlichung der Typformatierung bei den Attributen (<code>+ id: PositiveInteger [0..1]</code>, <code>+ memoryHighAddress: PositiveInteger [0..1]</code>, <code>+ memoryHighAddressLabel: String [0..1]</code>, <code>+ memoryLowAddress: PositiveInteger [0..1]</code>, <code>+ memoryLowAddressLabel: String [0..1]</code>) durch Schließen der Leerzeichen vor den Doppelpunkten.</li>\n</ul>"}]};
